import math


def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    prefix = [0] * (n + 1)
    for i, value in enumerate(a):
        prefix[i + 1] = prefix[i] + value

    hull = []
    best_num = 0
    best_den = 1

    def slope_le(i: int, j: int, right: int) -> bool:
        return (prefix[right] - prefix[i]) * (right - j) <= (prefix[right] - prefix[j]) * (right - i)

    for right in range(k, n + 1):
        left = right - k
        while len(hull) >= 2:
            a1 = hull[-2]
            b1 = hull[-1]
            cross = (b1 - a1) * (prefix[left] - prefix[b1]) - (prefix[b1] - prefix[a1]) * (left - b1)
            if cross <= 0:
                hull.pop()
            else:
                break
        hull.append(left)

        lo = 0
        hi = len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if slope_le(hull[mid], hull[mid + 1], right):
                lo = mid + 1
            else:
                hi = mid
        chosen = hull[lo]
        num = prefix[right] - prefix[chosen]
        den = right - chosen
        if num * best_den > best_num * den:
            best_num = num
            best_den = den

    g = math.gcd(best_num, best_den)
    return [best_num // g, best_den // g]
